/* From Uiverse.io by vinodjangid07  - Tags: animation, button, edit, hover effect */
.__UIV_SCOPE__ .editBtn {
  width: 55px;
  height: 55px;
  border-radius: 20px;
  border: none;
  background-color: rgb(93, 93, 116);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0px 5px 10px rgba(0, 0, 0, 0.123);
  cursor: pointer;
  position: relative;
  overflow: hidden;
  transition: all 0.3s;
}
.__UIV_SCOPE__ .editBtn::before {
  content: "";
  width: 200%;
  height: 200%;
  background-color: rgb(102, 102, 141);
  position: absolute;
  z-index: 1;
  transform: scale(0);
  transition: all 0.3s;
  border-radius: 50%;
  filter: blur(10px);
}
.__UIV_SCOPE__ .editBtn:hover::before {
  transform: scale(1);
}
.__UIV_SCOPE__ .editBtn:hover {
  box-shadow: 0px 5px 10px rgba(0, 0, 0, 0.336);
}

.__UIV_SCOPE__ .editBtn svg {
  height: 17px;
  fill: white;
  z-index: 3;
  transition: all 0.2s;
  transform-origin: bottom;
}
.__UIV_SCOPE__ .editBtn:hover svg {
  transform: rotate(-15deg) translateX(5px);
}
.__UIV_SCOPE__ .editBtn::after {
  content: "";
  width: 25px;
  height: 1.5px;
  position: absolute;
  bottom: 19px;
  left: -5px;
  background-color: white;
  border-radius: 2px;
  z-index: 2;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.5s ease-out;
}
.__UIV_SCOPE__ .editBtn:hover::after {
  transform: scaleX(1);
  left: 0px;
  transform-origin: right;
}
